from pathlib import Path

from app.utils.node import package_manager_prepare_target


def test_yarn_v1_lock_uses_yarn_classic(tmp_path: Path) -> None:
    (tmp_path / "package.json").write_text('{"name":"legacy-app"}\n', encoding="utf-8")
    (tmp_path / "yarn.lock").write_text(
        "# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n"
        "# yarn lockfile v1\n",
        encoding="utf-8",
    )

    assert package_manager_prepare_target(tmp_path, "yarn") == "yarn@1.22.22"


def test_declared_package_manager_version_takes_priority(tmp_path: Path) -> None:
    (tmp_path / "package.json").write_text(
        '{"name":"berry-app","packageManager":"yarn@4.5.1"}\n',
        encoding="utf-8",
    )
    (tmp_path / "yarn.lock").write_text("# yarn lockfile v1\n", encoding="utf-8")

    assert package_manager_prepare_target(tmp_path, "yarn") == "yarn@4.5.1"
